/* ---- varlena/text shim (4-byte header only; driver-built values) ---- */
typedef struct varlena
{
	char		vl_len_[4];
	char		vl_dat[];
} varlena;
typedef struct varlena text;

#define VARHDRSZ ((int32) sizeof(int32))

static inline void
SET_VARSIZE(void *p, Size total)
{
	uint32		v = ((uint32) total) << 2;

	memcpy(p, &v, 4);
}

static inline Size
VARSIZE(const void *p)
{
	uint32		v;

	memcpy(&v, p, 4);
	return v >> 2;
}

#define VARDATA(p) (((char *) (p)) + VARHDRSZ)
#define VARDATA_ANY(p) VARDATA(p)
#define VARSIZE_ANY_EXHDR(p) (VARSIZE(p) - VARHDRSZ)
#define unconstify(type, expr) ((type) (uintptr_t) (expr))

static text *
cstring_to_text_with_len(const char *s, int len)
{
	text	   *result = (text *) palloc(len + VARHDRSZ);

	SET_VARSIZE(result, len + VARHDRSZ);
	memcpy(VARDATA(result), s, len);
	return result;
}

static text *
cstring_to_text(const char *s)
{
	return cstring_to_text_with_len(s, strlen(s));
}

static char *
text_to_cstring(const text *t)
{
	int			len = VARSIZE_ANY_EXHDR(t);
	char	   *result = (char *) palloc(len + 1);

	memcpy(result, VARDATA_ANY(t), len);
	result[len] = '\0';
	return result;
}

