static void
deconstruct_array_builtin(ArrayType *array, Oid elmtype,
						  Datum **elemsp, bool **nullsp, int *nelemsp)
{
	int			n = array->nelems;
	Datum	   *elems = (Datum *) palloc(sizeof(Datum) * (n > 0 ? n : 1));
	bool	   *nulls = (bool *) palloc(sizeof(bool) * (n > 0 ? n : 1));

	(void) elmtype;
	memcpy(elems, array->elems, sizeof(Datum) * n);
	memcpy(nulls, array->nulls, sizeof(bool) * n);
	*elemsp = elems;
	*nullsp = nulls;
	*nelemsp = n;
}

static bool
array_contains_nulls(ArrayType *array)
{
	for (int i = 0; i < array->nelems; i++)
		if (array->nulls[i])
			return true;
	return false;
}

