/* ---- minimal chained hash honoring the caller's match fn ---- */
typedef uint32 (*HashValueFunc) (const void *key, Size keysize);
typedef int (*HashCompareFunc) (const void *key1, const void *key2, Size keysize);

typedef struct HASHCTL
{
	Size		keysize;
	Size		entrysize;
	MemoryContext hcxt;
	HashValueFunc hash;
	HashCompareFunc match;
} HASHCTL;

#define HASH_ELEM 0x0001
#define HASH_CONTEXT 0x0002
#define HASH_FUNCTION 0x0004
#define HASH_COMPARE 0x0008

typedef enum
{
	HASH_FIND,
	HASH_ENTER
} HASHACTION;

#define PG_JSONFAM_NBUCKETS 256

typedef struct PgJsonfamHashChain
{
	struct PgJsonfamHashChain *next;
	/* entry data (entrysize bytes) follows */
} PgJsonfamHashChain;

typedef struct HTAB
{
	HASHCTL		ctl;
	PgJsonfamHashChain *buckets[PG_JSONFAM_NBUCKETS];
} HTAB;

static HTAB *
hash_create(const char *tabname, long nelem, const HASHCTL *info, int flags)
{
	HTAB	   *h = (HTAB *) palloc0(sizeof(HTAB));

	(void) tabname;
	(void) nelem;
	(void) flags;
	h->ctl = *info;
	return h;
}

static void *
hash_search(HTAB *hashp, const void *keyPtr, HASHACTION action, bool *foundPtr)
{
	uint32		hv = hashp->ctl.hash(keyPtr, hashp->ctl.keysize);
	uint32		b = hv % PG_JSONFAM_NBUCKETS;
	PgJsonfamHashChain *c;

	for (c = hashp->buckets[b]; c != NULL; c = c->next)
	{
		void	   *ekey = (char *) c + sizeof(PgJsonfamHashChain);

		if (hashp->ctl.match(ekey, keyPtr, hashp->ctl.keysize) == 0)
		{
			if (foundPtr)
				*foundPtr = true;
			return ekey;
		}
	}
	if (action == HASH_ENTER)
	{
		c = (PgJsonfamHashChain *) palloc(sizeof(PgJsonfamHashChain) +
										  hashp->ctl.entrysize);
		memcpy((char *) c + sizeof(PgJsonfamHashChain), keyPtr,
			   hashp->ctl.keysize);
		c->next = hashp->buckets[b];
		hashp->buckets[b] = c;
		if (foundPtr)
			*foundPtr = false;
		return (char *) c + sizeof(PgJsonfamHashChain);
	}
	if (foundPtr)
		*foundPtr = false;
	return NULL;
}

/* FNV-1a stand-ins: only bucket distribution depends on these. */
static uint32
hash_bytes(const unsigned char *k, int keylen)
{
	uint32		h = 2166136261u;

	for (int i = 0; i < keylen; i++)
	{
		h ^= k[i];
		h *= 16777619u;
	}
	return h;
}

static uint32
hash_bytes_uint32(uint32 k)
{
	return hash_bytes((const unsigned char *) &k, sizeof(k));
}

/* ---- UTF8-pinned mblen clamp (feeds only the discarded CONTEXT text) ---- */
static int
pg_mblen_range(const char *s, const char *e)
{
	int			l = pg_utf_mblen((const unsigned char *) s);

	if (l > e - s)
		l = (int) (e - s);
	return l;
}

